use std::sync::Mutex;

async fn fetch() -> i32 { 10 }

async fn update(m: &Mutex<i32>) -> i32 {
    let val = ⟦guard_expr⟧;
    let data = fetch()⟦await_expr⟧;
    data + val
}

fn assert_send<T: Send>(_t: T) {}

fn main() {
    let m = Mutex::new(5);
    assert_send(update(&m));
}

